package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7b; import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test;
class GovernanceScaleupHeldOutProtectionTest { @Test void newHeldOutCasesAreReservedAndExclusive() throws Exception { var h=Stage7BGovernanceDatasetSupport.cases().stream().filter(v->"test".equals(v.split())).map(Stage7BGovernanceDatasetSupport.CaseView::benchmarkCase).filter(c->c.caseId.startsWith("stage7b-")).toList(); assertThat(h).hasSize(36); assertThat(h).allSatisfy(c->{assertThat(c.reservedForHeldOut).isTrue(); assertThat(c.tags).contains("HELD_OUT"); assertThat(c.humanReviewed).isFalse();}); assertThat(Stage7BGovernanceDatasetSupport.crossSplitRootCount()).isZero(); }}
